(() => {
 const bundles=[
 {id:'outpatient',name:'Outpatient Gynecology & Antenatal Suite',tag:'Outpatient clinic',price:24900,description:'A complete consultation and antenatal examination setup.',items:[['electric-gynaecology-examination-chair',1],['edan-c6a-video-colposcope',1],['aveus-av-classic-3-fetal-monitor',1],['jumper-jpd-100e-fetal-doppler-with-tft-display',1]],includes:'Turnkey wiring, calibration and licensing documentation included.',room:true,image:'/assets/clinical-room-hospital-v2.webp'},
 {id:'procedure',name:'Cervical Diagnostics, LEEP & Minor Surgery Suite',tag:'Clinical procedure room',price:24500,description:'Equipment for cervical screening, electrosurgery and minor procedures.',items:[['led-spa-surtron-80-electro-surgery-unit',1],['basco-india-cryo-004-deluxe-cryosurgical-system',1],['askir-c30-professional-electric-surgical-suction-machine-ca-mi',1],['tsunlandscope-portable-electronic',1],['gynecology-examination-couch-manual-uae',1]],includes:'Five complementary equipment systems for your procedure suite.',room:true,image:'/assets/clinical-procedure-room.webp'},
 {id:'maternity',name:'Comprehensive Hospital Maternity & Diagnostic Center',tag:'Hospital department',price:50900,description:'A larger equipment bundle for maternity wards and diagnostic departments.',items:[['electric-gynaecology-examination-chair',2],['edan-c6a-video-colposcope',1],['aveus-av-classic-3-fetal-monitor',2],['led-spa-surtron-80-electro-surgery-unit',1],['askir-c30-professional-electric-surgical-suction-machine-ca-mi',1],['basco-india-cryo-004-deluxe-cryosurgical-system',1],['jumper-jpd-100e-fetal-doppler-with-tft-display',4]],includes:'Two-year comprehensive AMC and priority loaner support included.',room:true,image:'/assets/clinical-maternity-room.webp'}
 ];
 const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=v=>'AED '+Number(v).toLocaleString('en-AE');
 document.addEventListener('DOMContentLoaded',async()=>{
  const room=document.getElementById('clinical-room-explorer'),legacy=document.querySelector('.packages-page-wrapper');if(!room||!legacy)return;
  room.hidden=true;legacy.hidden=true;legacy.classList.add('bundle-legacy-hidden');
  const host=document.createElement('section');host.className='bundle-showcase';host.id='bundle-showcase';room.before(host);
  const detail=document.createElement('section');detail.className='bundle-detail';detail.hidden=true;room.after(detail);
  let products=[];try{const r=await fetch('https://api.gynaeq.com/api/data');if(!r.ok)throw Error();products=(await r.json()).products||[]}catch{try{products=(await(await fetch('/data/catalog.json')).json()).products||[]}catch{}}
  const product=id=>products.find(p=>p.id===id);
  const collage=b=>`<div class="bundle-collage">${b.items.slice(0,4).map(([id])=>{const p=product(id);return p?`<img src="${e(p.image)}" alt="${e(p.title||p.name)}">`:''}).join('')}</div>`;
  host.innerHTML=`<div class="bundle-gallery-heading"><span>Choose your clinical setup</span><h2>Three bundles. One complete solution.</h2><p>Choose a suite to explore its equipment, individual products and package price.</p></div><div class="bundle-gallery">${bundles.map((b,i)=>`<article class="bundle-gallery-card">${b.room?'<img class="bundle-room-thumb" src="${b.image}" alt="Hospital examination room concept">':collage(b)}<div class="bundle-gallery-body"><span class="bundle-tag">${e(b.tag)}</span><h3>${e(b.name)}</h3><p>${e(b.description)}</p><div class="bundle-card-meta"><strong>${money(b.price)}</strong><span>${b.items.reduce((sum,x)=>sum+x[1],0)} equipment units</span></div><a class="bundle-enter" href="#bundle=${b.id}">Explore this suite <span>→</span></a></div></article>`).join('')}</div>`;
  function render(){const id=new URLSearchParams(location.hash.slice(1)).get('bundle');const b=bundles.find(b=>b.id===id);host.hidden=!!b;detail.hidden=!b;room.hidden=!(b?.room);room.classList.toggle('bundle-room-visible',!!b?.room);
   if(!b){detail.innerHTML='';return;}
   detail.innerHTML=`<div class="bundle-detail-heading"><a href="#bundles" class="bundle-back">← All clinical suites</a><span class="bundle-tag">${e(b.tag)}</span><h2>${e(b.name)}</h2><p>${e(b.description)}</p></div>${!b.room?`<div class="bundle-equipment-stage">${collage(b)}<p>Actual equipment included in this bundle. Room visualization coming separately for this setup.</p></div>`:''}<div class="bundle-summary"><div><span>Complete package</span><strong>${money(b.price)}</strong><p>${e(b.includes)}</p></div><a href="/contact?package=${encodeURIComponent(b.name)}" class="bundle-enter">Request a suite quotation →</a></div><div class="bundle-products-heading"><h2>Equipment in this suite</h2><p>Browse each product just like the shop. Quantities shown are included in this package.</p></div><div class="bundle-product-grid">${b.items.map(([id,qty])=>{const p=product(id);if(!p)return '';const price=Number(p.salePrice||p.price||p.sellingPrice||0);return `<article class="bundle-product-card"><a href="/product?id=${encodeURIComponent(id)}" class="bundle-product-photo"><span class="bundle-quantity">${qty} ${qty===1?'unit':'units'} included</span><img src="${e(p.image)}" alt="${e(p.title||p.name)}" loading="lazy"></a><div class="bundle-product-body"><span class="bundle-product-brand">${e(p.brand)}</span><a class="bundle-product-title" href="/product?id=${encodeURIComponent(id)}">${e(p.title||p.name)}</a><p class="bundle-product-price">${price?money(price):'Request price'} <small>/ unit</small></p>${qty>1?`<p class="bundle-line-total">${qty} units · ${money(price*qty)}</p>`:''}<a class="bundle-product-link" href="/product?id=${encodeURIComponent(id)}">View product →</a></div></article>`}).join('')}</div><a class="bundle-back" href="#bundles">← Explore other suites</a>`;
   const positions=b.id==='procedure'?[[17,31],[16,65],[82,36],[92,49],[45,46]]:b.id==='maternity'?[[32,48],[51,20],[85,32],[65,44],[88,55],[66,63],[8,44]]:[[40,54],[62,30],[87,44],[10,47]];
   window.renderClinicalRoom?.({image:b.image,items:b.items.map(([id],i)=>({id,name:product(id)?.name||product(id)?.title||'Equipment',x:positions[i][0],y:positions[i][1]}))});
   const intro=detail.querySelector('.bundle-detail-heading');room.before(intro);document.querySelectorAll('.bundle-detail-heading').forEach(n=>{if(n!==intro)n.remove()});intro.classList.add('bundle-standalone-heading');intro.scrollIntoView({block:'start',behavior:'auto'});
  }
  window.addEventListener('hashchange',()=>{document.querySelector('.bundle-standalone-heading')?.remove();render()});render();
 });
})();
